const steeds = [ 'S_QUADRUPED', 'S_UNICORN', 'S_ANGEL',
                                        'S_CENTAUR',   'S_DRAGON',  'S_JABBERWOCK',
                                        0 ];




/* caller has decided that hero can't reach something while mounted */
function rider_cant_reach()
{
    C.You("aren't skilled enough to reach from %s.", C.y_monnam(C.mount()));
}

/*** Putting the saddle on ***/

/* Can this monster wear a saddle? */
function can_saddle(mtmp)
