    let ptr;
    let chance;

    if (!C.u_handsy())
        return C.ECMD_OK;

    /* Select an animal */
    if (C.u.uswallow || C.Underwater || !C.getdir(0)) {
        C.pline1(C.Never_mind);
        return C.ECMD_CANCEL;
    }
    if (!C.u.dx && !C.u.dy) {
        C.pline("Saddle yourself?  Very funny...");
        return C.ECMD_OK;
    }
